	//   submatrix 3 = [u, dRu, dZu, dRRu, dZZu].
	jacobian_submatrix_3[0] = -pow(dRu2, 2)*dr2*dzodr*h2*pow(ri, 2)/alpha2 - pow(dZu2, 2)*dr2*drodz*h2*pow(ri, 2)/alpha2;
