	//   submatrix 4 = [u, dRu, dZu, dRRu, dZZu].
	jacobian_submatrix_4[0] = 8*M_PI*a2*dr2*dzodr*m2*phi2 - 16*M_PI*a2*dr2*dzodr*phi2*pow(wplOmega, 2)/alpha2;
