	ja[offset1 +  15] = BASE + 1 * dim + IDX(i, j + 2);
	ja[offset1 +  16] = BASE + 1 * dim + IDX(i + 1, j);
	ja[offset1 +  17] = BASE + 1 * dim + IDX(i + 2, j);
	ja[offset1 +  18] = BASE + 2 * dim + IDX(i - 2, j);
	ja[offset1 +  19] = BASE + 2 * dim + IDX(i - 1, j);
