	jacobian_submatrix_2[0] = -16*M_PI*a2*dr2*dzodr*pow(l, 2)*phi2or2/h2;
	jacobian_submatrix_2[1] = -dRu1*dzodr + 3*dRu3*dzodr + 3*dzodr/ri;
