	//   submatrix 3 = [u, dRu, dZu, dRRu, dZZu].
	jacobian_submatrix_3[0] = 32*M_PI*a2*dr2*dzodr*l*phi2or2*wplOmega/h2;
	jacobian_submatrix_3[1] = 3*dRu2*dzodr;
	jacobian_submatrix_3[2] = 3*dZu2*drodz;
	jacobian_submatrix_3[3] = 0;
