	aa[offset2 +  15] = +D13*jacobian_submatrix_2[1]+D23*jacobian_submatrix_2[3];
	aa[offset2 +  16] = +D14*jacobian_submatrix_2[1]+D24*jacobian_submatrix_2[3];
	aa[offset2 +  17] = +D10*jacobian_submatrix_3[1];
