	aa[offset2 +  27] = +1.0*jacobian_submatrix_5[0];
	aa[offset2 +  28] = jacobian_submatrix_w;

	// Columns.
	ja[offset2 +   0] = BASE + 0 * dim + IDX(i - 2, j);
	ja[offset2 +   1] = BASE + 0 * dim + IDX(i - 1, j);
	ja[offset2 +   2] = BASE + 0 * dim + IDX(i, j - 2);
