	jacobian_submatrix_3[0] = -16*M_PI*a2*dr2*dzodr*pow(l, 2)*phi2or2/h2 + pow(dRu2, 2)*dr2*dzodr*h2*pow(ri, 2)/alpha2 + pow(dZu2, 2)*dr2*drodz*h2*pow(ri, 2)/alpha2;
	jacobian_submatrix_3[1] = dRu1*dzodr + 2*dRu3*dzodr + 2*dzodr/ri;
