	ja[offset3 +  10] = BASE + 1 * dim + IDX(i - 2, j);
	ja[offset3 +  11] = BASE + 1 * dim + IDX(i - 1, j);
	ja[offset3 +  12] = BASE + 1 * dim + IDX(i, j - 3);
