	// Columns.
	ja[offset4 +   0] = BASE + 0 * dim + IDX(i - 3, j);
	ja[offset4 +   1] = BASE + 0 * dim + IDX(i - 2, j);
	ja[offset4 +   2] = BASE + 0 * dim + IDX(i - 1, j);
